style.css:
/* Dark Soft Coquette ♡ */
body {
  background: #21191E !important;
  color: #F5DDE6 !important;
}
h1, h2, h3 { color: #E9A1B5 !important; }
p { color: #D2B5C0 !important; }
a { color: #F0AFC4 !important; }
button {
  background: #70485B !important;
  color: #FFF0F5 !important;
  border: 1px solid #A66F83 !important;
  border-radius: 12px !important;
}
input, textarea {
  background: #30232B !important;
  color: #F5DDE6 !important;
  border: 1px solid #80566A !important;
}
::selection { background: #A66F83; color: white; }
